            const auto i = args.indexOf ("--reloadtest");
            runReloadTest (args[i + 1].unquoted(), args[i + 2].unquoted(),
                           i + 3 < args.size() && ! args[i + 3].startsWith ("--") ? args[i + 3].unquoted() : juce::String(), args.contains ("--wait-kill"));
