        if (args.contains ("--leftovers190nrtest"))
        {
            // round 190nr: going back to an older version removes what newer versions added to the install folder
            // (the --apply-update helper's step after the installer). Prints "result=OK" or the failing check.
            const auto root = juce::File::createTempFile ("yw-leftovers190nr");
            juce::StringArray fails;
            auto run = [&] (const juce::String& version, bool licensesGone, bool listGone) {
                root.deleteRecursively();
                root.getChildFile ("install/licenses").createDirectory();
                root.getChildFile ("install/licenses/onnxruntime-LICENSE.txt").replaceWithText ("x");
                root.getChildFile ("install/YW Studio.exe").replaceWithText ("x");
                root.getChildFile ("install/installed-files.txt").replaceWithText ("YW Studio.exe\r\nlicenses\r\n");
                root.getChildFile ("install/My notes.txt").replaceWithText ("x");
                root.getChildFile ("update/installing.txt").create();
                if (version.isNotEmpty())
                    root.getChildFile ("update/installing.txt").replaceWithText ("from=0.1.31\nrollback=1\nversion=" + version + "\n");
                const auto removed = yw::updater::removeNewerLeftovers (root.getChildFile ("install"), root.getChildFile ("update/installing.txt"));
                const auto in = root.getChildFile ("install");
                if (in.getChildFile ("licenses").exists() == licensesGone) fails.add (version + ": licenses");
                if (in.getChildFile ("installed-files.txt").exists() == listGone) fails.add (version + ": installed-files.txt");
                if (! in.getChildFile ("YW Studio.exe").existsAsFile() || ! in.getChildFile ("My notes.txt").existsAsFile()) fails.add (version + ": removed too much");
                std::printf ("%s -> removed [%s]\n", version.toRawUTF8(), removed.joinIntoString (", ").toRawUTF8());
            };
            run ("0.1.29-alpha", true, true);   // going back to 0.1.29: both newer entries go
            run ("0.1.28.1-alpha", true, true);
            run ("0.1.30-alpha", false, true);  // 0.1.30 installs licenses itself
            run ("0.1.31-alpha", false, false); // same or newer: nothing goes
            run ("0.1.32", false, false);
            run ("", false, false);             // unreadable note: nothing goes
            root.deleteRecursively();
            std::printf ("result=%s%s\n", fails.isEmpty() ? "OK" : "FAILED ", fails.joinIntoString ("; ").toRawUTF8());
            setApplicationReturnValue (fails.isEmpty() ? 0 : 1);
            quit();
            return;
        }

        if (args.contains ("--send-test-report"))
        {
            // YW.exe --send-test-report out.txt [--dry]: builds a crash report marked "test" from the newest crash /
            // hang file and this computer's facts, writes its JSON to out.txt.json and (without --dry) sends it to
            // yolo.su (YW_CRASH_ENDPOINT overrides); out.txt gets "id=…" and "result=OK" or the error (round 159)
            const auto i = args.indexOf ("--send-test-report");
            const juce::File out (args[i + 1].unquoted());
            yw::crashreporter::Session session;
            session.version = getApplicationVersion();
            for (const auto* pattern : { "crash *.txt", "hang *.txt" })
            {
                auto files = yw::platform::settingsFile ("autosave").findChildFiles (juce::File::findFiles, false, pattern);
                yw::filesort::byTime (files, yw::filesort::By::modificationTime, true);
                if (! files.isEmpty())
                    (juce::String (pattern).startsWith ("crash") ? session.crashFile : session.hangFile) = files[0];
            }
            session.steps = { "00:00:01 test report (YW Studio.exe --send-test-report)", "00:00:02 opening project " + out.getFileName() };
            auto input = yw::crashreporter::makeInput (session, session.crashFile.existsAsFile() ? "crash" : "manual", nullptr);
            input.test = true;
            const auto json = yw::crashreporter::buildJson (input, false);
            out.withFileExtension (out.getFileExtension() + ".json").replaceWithText (json);
            const auto error = args.contains ("--dry") ? juce::String() : yw::crashreporter::sendNow (json);
            out.replaceWithText ("id=" + juce::String::fromUTF8 (input.id.c_str()) + "\nendpoint=" + yw::crashreporter::endpoint() + "\nbytes="
                                 + juce::String (json.getNumBytesAsUTF8()) + "\nresult=" + (error.isEmpty() ? juce::String ("OK") : error) + "\n");
            setApplicationReturnValue (error.isEmpty() ? 0 : 1);
            quit();
            return;
        }

