            const auto plain = yw::olderyw::forRelease (song, "0.1.30");
            yw::Note a, b, slide;
            a.start = 0, a.length = 4 * yw::ppq, a.key = 60, a.channel = 0;
            b = a, b.key = 67;
            slide = a, slide.start = yw::ppq, slide.length = yw::ppq / 2, slide.slide = true;
            song.patterns[0].notes = { a, b, slide };
            song.channels[0].arp.direction = 1;
            song.channels[0].arp.slide = true;
            const auto copy = yw::olderyw::forRelease (song, "0.1.30");
