            plain.start = yw::ticksPerStep * 4, plain.channel = 0;
            notes = { held, plain };
            const auto json = yw::ProjectFile::toJson (song);
            juce::String why;
            const auto back = yw::ProjectFile::fromJson (json, why);
            const auto copy = yw::olderyw::forRelease (song, "0.1.30");
            const auto lines = (int) std::count_if (copy.lost.begin(), copy.lost.end(), [] (const yw::olderyw::Loss& l) {
                return juce::String (l.text).startsWith ("{0} FL step note(s) on generators") && l.detail == "1" && l.sound;
            });
