            yw::Automation ranged = linked;
            ranged.name = "Ranged";
            ranged.links.clear();
            ranged.target.kind = yw::AutomationTargetKind::mixerVolume;
            ranged.target.index = pad;
            ranged.rangeMin = 0.25f;
            ranged.rangeMax = 0.75f;
