            ui.setVisible (true);
            yw::DetailView::shownSetting = yw::DetailView::devicesPage = true;
            ui.setClipLaunchWorkflow (true);
            ui.showPanelsForSnapshot ({ yw::workspace::Panel::playlist });
            offline.editSong ([] (yw::Song& s) {
                while (s.patterns.empty())
                    s.patterns.emplace_back();
                yw::Note note;
                note.channel = 0;
                note.key = 60;
                s.patterns[0].name = "Choir";
                s.patterns[0].notes = { note };
                s.patterns[0].lengthTicks = 4 * yw::ppq;
                s.playlistTracks.resize (std::max<std::size_t> (s.playlistTracks.size(), 2));
                s.playlistTracks[0].name = "Helix";
                yw::Clip clip;
                clip.pattern = 0;
                clip.length = 4 * yw::ppq;
                yw::launcher::setClip (s, 0, 0, clip);
            }, false);
            offline.dispatchPendingMessages();
            auto* detail = ui.getDetailViewForSnapshot();
            check ("detail view", detail != nullptr);
