            saveWindow (yw::ui::makeTrackIconGrid (5, {}), "-trackicons168h.png"); // round 168h: the icon picker
            saveWindow (std::make_unique<yw::toolbar::CustomizePanel> (yw::toolbarlayout::Layout::makeDefault()), "-customize-toolbar.png");
            // two moved controls: Tools › Last tweaked and Add › Automation for last tweaked parameter show them (REA round 143)
            offline.noteTweaked ({ yw::AutomationTargetKind::channelVolume, 0 });
